package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.content.links.v1.*;
class NoteLinkActivityTest extends ActivityFixtures {
 static final String TOPIC="content.note-links.v1";
 WikiLinkV1.Builder link(){return WikiLinkV1.newBuilder().setLinkId(id().toString()).setOrdinal(0).setStartOffset(2).setEndOffset(40).setTargetToken("Original 한글").setLabel("<script>literal</script>").setFragment("section").setStatus("UNRESOLVED");}
 @Test void originalOccurrencesKeepUtf16OffsetsRequestedIdsAndAllResolutionStates()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_LINKS",id()));var p=NoteLinksChangedPayloadV1.parseFrom(env.getPayload());var target=id();var items=List.of(link(),link().setStatus("AMBIGUOUS"),link().setStatus("RESOLVED").setTargetNoteId(target.toString()),link().setStatus("TARGET_RETIRED").setTargetToken("note:"+target).setRequestedTargetId(target.toString()).setTargetNoteId(target.toString()).setEndOffset(55));var b=p.toBuilder().setLinkVersion(17).setNoteVersion(3);for(int i=0;i<items.size();i++)b.addLinks(items.get(i).setOrdinal(i).setStartOffset(100*i+2).setEndOffset(100*i+55));var raw=env.toBuilder().setPayload(b.build().toByteString()).build().toByteArray();var e=ActivityEvent.decode(TOPIC,raw);assertEquals(17,e.sourceVersion());assertEquals(3,e.noteLinks().noteVersion());assertEquals(p.getRevisionId(),e.noteLinks().revisionId().toString());assertEquals(List.of("UNRESOLVED","AMBIGUOUS","RESOLVED","TARGET_RETIRED"),e.noteLinks().links().stream().map(ActivityEvent.WikiLink::status).toList());assertEquals(2,e.noteLinks().links().getFirst().startOffset());assertEquals(target,e.noteLinks().links().getLast().requestedTargetId());assertTrue(ActivityEvent.target(e));ActivityEvent.transport(TOPIC,raw,e.aggregateId().toString(),headers(e));assertNull(e.metadata());}
 @Test void malformedOccurrenceIdsStatesBoundsAndBindingsNeverReachProjection()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_LINKS",id()));var p=NoteLinksChangedPayloadV1.parseFrom(env.getPayload());for(var bad:List.of(link().setLinkId("bad"),link().setOrdinal(1),link().setStartOffset(-1),link().setStartOffset(Integer.MAX_VALUE).setEndOffset(40),link().setEndOffset(32769),link().setEndOffset(5),link().setTargetToken(""),link().setTargetToken("x".repeat(201)),link().setTargetToken("[[x]]"),link().setTargetToken("x#fragment"),link().setStatus("RESOLVED"),link().setStatus("UNRESOLVED").setTargetNoteId(id().toString()),link().setStatus("OTHER"),link().setTargetToken("note:"+id()),link().setRequestedTargetId(id().toString()),link().setTargetToken("note:"+id()).setRequestedTargetId(id().toString())))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.toBuilder().addLinks(bad).build().toByteString()).build().toByteArray()));for(var bad:List.of(p.toBuilder().setLinkVersion(0),p.toBuilder().setNoteVersion(0),p.toBuilder().setSourceState("MERGED"),p.toBuilder().setSourceState("RETIRED").addLinks(link()),p.toBuilder().setSourceNoteId(id().toString()),p.toBuilder().setRevisionId("bad"),p.toBuilder().addLinks(link()).addLinks(link().setOrdinal(1))))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));}
 @Test void full256RepeatedOccurrencesAreDistinctAndRetirementIsEmpty()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_LINKS",id()));var p=NoteLinksChangedPayloadV1.parseFrom(env.getPayload()).toBuilder();for(int i=0;i<256;i++)p.addLinks(link().setOrdinal(i).setStartOffset(i*60).setEndOffset(i*60+55));assertEquals(256,ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.build().toByteString()).build().toByteArray()).noteLinks().links().size());p.addLinks(link().setOrdinal(256).setStartOffset(256*60).setEndOffset(256*60+55));assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.build().toByteString()).build().toByteArray()));p.clearLinks().setSourceState("RETIRED");assertTrue(ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(p.build().toByteString()).build().toByteArray()).noteLinks().links().isEmpty());}
 @Test void legacyJsonAndCursorsRemainCompatible(){var json=tools.jackson.databind.json.JsonMapper.builder().build();var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE_METADATA"),wire("NOTE_METADATA",id()));var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(e);tree.remove("noteLinks");assertEquals(e,json.treeToValue(tree,ActivityEvent.class));var space=id();var row=ActivityEvent.decode(TOPIC,wire("NOTE_LINKS",space));var q=ActivityQuery.parse(space,ActivityQueryTest.params("kind","NOTE_LINKS","timezone","UTC"));var params=ActivityQueryTest.params("kind","NOTE_LINKS","timezone","UTC","before",q.cursor(row));assertEquals(row.eventId(),ActivityQuery.parse(space,params).event());params.put("kind",new String[]{"NOTE"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(space,params));}
}
